// progress-domain.js: pure rules, no browser globals.
export function createProgress(storage) {        // storage port: { load(), save(data) }.
  return {
    complete(lessonId, quizPassed) {
      if (!quizPassed) return false;
      const data = storage.load() ?? { done: [] };
      if (!data.done.includes(lessonId)) data.done.push(lessonId);
      storage.save(data);
      return true;
    },
  };
}

// local-storage-adapter.js: the only file that knows localStorage.
export const localStore = {
  load: () => JSON.parse(localStorage.getItem("progress") ?? "null"),
  save: (d) => localStorage.setItem("progress", JSON.stringify(d)),
};

// main.js: wires the edges to the core.
import { createProgress } from "./progress-domain.js";
import { localStore } from "./local-storage-adapter.js";
export const progress = createProgress(localStore);
